ace App\\Http\\Controllers\\Api;\n\nuse App\\Http\\Controllers\\Controller;\nuse App\\Mail\\CommandeAdminMail;\nuse App\\Mail\\CommandeConfirmationMail;\nuse App\\Models\\Commande;\nuse App\\Models\\Product;\nuse Barryvdh\\DomPDF\\Facade\\Pdf;\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Support\\Facades\\DB;\nuse Illuminate\\Support\\Facades\\Log;\nuse Illuminate\\Support\\Facades\\Mail;\nuse Illuminate\\Support\\Str;\nuse Illuminate\\Validation\\ValidationException;\n\nclass CommandeController extends Controller\n{\n    public function store(Request $request)\n    {\n        $validated = $request->validate([\n            \'type_client\' => [\'required\', \'in:particulier,entreprise\'],\n            \'nom\' => [\'required\', \'string\', \'max:255\'],\n            \'raison_sociale\' => [\'required_if:type_client,entreprise\', \'nullable\', \'string\', \'max:255\'],\n            \'email\' => [\'required\', \'email\', \'max:255\'],\n            \'telephone\' => [\'required\', \'string\', \'max:50\'],\n            \'items\' => [\'required\', \'array\', \'min:1\'],\n            \'items.*.product_id\' => [\'required\', \'integer\', \'exists:products,id\'],\n            \'items.*.quantite\' => [\'required\', \'integer\', \'min:1\'],\n        ]);\n\n        $commande = DB::transaction(function () use ($validated) {\n            do {\n                $reference = \'CMD-\' . now()->format(\'Ymd\') . \'-\' . strtoupper(Str::random(5));\n            } while (Commande::where(\'reference\', $reference)->exists());\n\n            $commande = Commande::create([\n                \'reference\' => $reference,\n                \'type_client\' => $validated[\'type_client\'],\n                \'nom\' => $validated[\'nom\'],\n                \'raison_sociale\' => $validated[\'type_client\'] === \'entreprise\' ? $validated[\'raison_sociale\'] : null,\n                \'email\' => $validated[\'email\'],\n                \'telephone\' => $validated[\'telephone\'],\n                \'total\' => 0,\n                \'statut\' => \'recue\',\n            ]);\n\n            $totalCommande = 0;\n\n            foreach ($validated[\'items\'] as $item) {\n                $produit = Product::query()->whereKey($item[\'product_id\'])->lockForUpdate()->first();\n\n                if (!$produit || !$produit->stock || $produit->price === null) {\n                    throw ValidationException::withMessages([\n                        \'items\' => [\'Un des produits sélectionnés n’est plus disponible ou est sur devis.\'],\n                    ]);\n                }\n\n                $quantite = (int) $item[\'quantite\'];\n                $prixUnitaire = (float) $produit->price;\n                $totalLigne = $prixUnitaire * $quantite;\n\n                $commande->items()->create([\n                    \'product_id\' => $produit->id,\n                    \'designation\' => $produit->name,\n                    \'quantite\' => $quantite,\n                    \'prix_unitaire\' => $prixUnitaire,\n                    \'total_ligne\' => $totalLigne,\n                ]);\n\n                $totalCommande += $totalLigne;\n            }\n\n            $commande->update([\'total\' => $totalCommande]);\n\n            return $commande;\n        });\n\n        $commande->load(\'items\');\n\n        /*\n        |--------------------------------------------------------------------------\n        | GÉNÉRATION DU PDF\n        |--------------------------------------------------------------------------\n        */\n        $pdfData = null;\n        try {\n            $pdf = Pdf::loadView(\'pdf.commande\', [\'commande\' => $commande])->setPaper(\'a4\', \'portrait\');\n            $pdfData = $pdf->output();\n        } catch (\\Throwable $e) {\n            Log::error(\'Erreur génération PDF commande: \' . $e->getMessage());\n        }\n\n        /*\n        |--------------------------------------------------------------------------\n        | ENVOI EMAIL PLANETECH (ADMIN) - TEST ENVOI DIRECT (send)\n        |--------------------------------------------------------------------------\n        */\n        if ($pdfData !== null) {\n            try {\n                $emailPlanetech = config(\'mail.admin_address\') ?? config(\'mail.from.address\');\n\n                // Utilisation de ->send() au lieu de ->queue() pour tester instantanément\n                Mail::to($emailPlanetech)->send(new CommandeAdminMail($commande, $pdfData));\n\n                Log::info(\'Email PLANETECH envoyé avec succès à \' . $emailPlanetech);\n            } catch (\\Throwable $e) {\n                Log::error(\'Erreur envoi email PLANETECH : \' . $e->getMessage());\n            }\n        }\n\n        /*\n        |--------------------------------------------------------------------------\n        | ENVOI EMAIL CLIENT - TEST ENVOI DIRECT (send)\n        |--------------------------------------------------------------------------\n        */\n        try {\n            Mail::to($commande->email)->send(new CommandeConfirmationMail($commande));\n            Log::info(\'Email client envoyé avec succès à \' . $commande->email);\n        } catch (\\Throwable $e) {\n            Log::error(\'Erreur envoi email client : \' . $e->getMessage());\n        }\n\n        return response()->json([\n            \'success\' => true,\n            \'message\' => \'Votre commande a été enregistrée avec succès.\',\n            \'reference\' => $commande->reference,\n            \'commande\' => $commande,\n        ], 201);\n    }\n}','envoye','2026-09-29 07:24:39','2026-09-29 07:29:01'),(22,'DEV-6ABB77D54709F','societe','hygvugyuvyg','uvyvghy','delerethice@gmail.com','+229','25525555','informatique','planetechsarlbeninplanetechsarlbeninplanetechsarlbeninplanetechsarlbeninplanetechsarlbeninplanetechsarlbeninplanetechsarlbeninplanetechsarlbeninplanetechsarlbeninplanetechsarlbenin','en_attente','2026-09-29 07:33:25','2026-09-29 07:33:25'),(23,'DEV-6ABB798017BDA','societe','uyghgbiy','yuftt-gyè','delerethice@gmail.com','+229','25525252','informatique','tyxtdrcvut-yxeycvygtvggv_```jsx\nimport { useRef } from \'react\';\n\nimport { useDevisForm } from \'@/hooks/useDevisForm\';\nimport { Champ, Saisie, ZoneTexte, Selection } from \'@/components/ui/Champ\';\nimport Bouton from \'@/components/ui/Bouton\';\nimport { EXPERTISES } from \'@/data/expertises\';\nimport { cn } from \'@/utils/cn\';\n\nconst TYPES_CLIENT = [\n  {\n    valeur: \'societe\',\n    libelle: \'Société\',\n    detail: \'Entreprise, ONG, administration\',\n  },\n  {\n    valeur: \'particulier\',\n    libelle: \'Personne physique\',\n    detail: \'Particulier, artisan\',\n  },\n];\n\nexport default function FormulaireDevis() {\n  const {\n    valeurs,\n    erreurs,\n    envoiEnCours,\n    succes,\n    erreurGlobale,\n    modifier,\n    soumettre,\n    reinitialiser,\n  } = useDevisForm();\n\n  // Verrou immédiat contre les soumissions répétées.\n  const soumissionVerrouillee = useRef(false);\n\n  const gererSoumission = async (event) => {\n    if (soumissionVerrouillee.current || envoiEnCours) {\n      event.preventDefault();\n      return;\n    }\n\n    soumissionVerrouillee.current = true;\n\n    try {\n      await soumettre(event);\n    } finally {\n      soumissionVerrouillee.current = false;\n    }\n  };\n\n  if (succes) {\n    return (\n      <div className=\"rounded-2xl border border-forest-100 bg-forest-50 p-8\">\n        <h3 className=\"text-xl font-semibold\">Demande envoyée</h3>\n\n        <p className=\"mt-3 max-w-prose text-slate-muted\">\n          Nous avons bien reçu votre demande et revenons vers vous sous\n          48 heures ouvrées.\n          {succes.reference && (\n            <>\n              {\' \'}Conservez la référence{\' \'}\n              <strong className=\"text-forest-700\">\n                {succes.reference}\n              </strong>{\' \'}\n              pour tout échange.\n            </>\n          )}\n        </p>\n\n        <Bouton\n          onClick={reinitialiser}\n          variante=\"contour\"\n          className=\"mt-6\"\n        >\n          Envoyer une autre demande\n        </Bouton>\n      </div>\n    );\n  }\n\n  return (\n    <form\n      onSubmit={gererSoumission}\n      noValidate\n      className=\"space-y-7\"\n    >\n      {erreurGlobale && (\n        <p\n          role=\"alert\"\n          className=\"rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700\"\n        >\n          {erreurGlobale}\n        </p>\n      )}\n\n      <fieldset>\n        <legend className=\"text-sm font-semibold text-forest-700\">\n          Vous êtes\n        </legend>\n\n        <div className=\"mt-3 grid gap-3 sm:grid-cols-2\">\n          {TYPES_CLIENT.map((type) => (\n            <label\n              key={type.valeur}\n              className={cn(\n                \'cursor-pointer rounded-xl border p-4 transition-colors\',\n                valeurs.type_client === type.valeur\n                  ? \'border-signal bg-forest-50\'\n                  : \'border-forest-100 hover:border-forest-200\'\n              )}\n            >\n              <input\n                type=\"radio\"\n                name=\"type_client\"\n                value={type.valeur}\n                checked={valeurs.type_client === type.valeur}\n                onChange={(e) =>\n                  modifier(\'type_client\', e.target.value)\n                }\n                className=\"sr-only\"\n              />\n\n              <span className=\"block font-semibold text-ink\">\n                {type.libelle}\n              </span>\n\n              <span className=\"mt-1 block text-xs text-slate-muted\">\n                {type.detail}\n              </span>\n            </label>\n          ))}\n        </div>\n      </fieldset>\n\n      {valeurs.type_client === \'societe\' && (\n        <Champ\n          id=\"raison_sociale\"\n          label=\"Nom de la société\"\n          erreur={erreurs.raison_sociale}\n        >\n          <Saisie\n            id=\"raison_sociale\"\n            name=\"raison_sociale\"\n            value={valeurs.raison_sociale}\n            onChange={(e) =>\n              modifier(\'raison_sociale\', e.target.value)\n            }\n            placeholder=\"Ex. PLANETECH SARL\"\n            erreur={erreurs.raison_sociale}\n          />\n        </Champ>\n      )}\n\n      <div className=\"grid gap-6 sm:grid-cols-2\">\n        <Champ\n          id=\"nom\"\n          label={\n            valeurs.type_client === \'societe\'\n              ? \'Nom du contact\'\n              : \'Nom et prénom\'\n          }\n          erreur={erreurs.nom}\n        >\n          <Saisie\n            id=\"nom\"\n            name=\"nom\"\n            value={valeurs.nom}\n            onChange={(e) => modifier(\'nom\', e.target.value)}\n            placeholder=\"Ex. Armelle Assogba\"\n            erreur={erreurs.nom}\n          />\n        </Champ>\n\n        <Champ\n          id=\"email\"\n          label=\"Adresse email\"\n          erreur={erreurs.email}\n        >\n          <Saisie\n            id=\"email\"\n            name=\"email\"\n            type=\"email\"\n            inputMode=\"email\"\n            value={valeurs.email}\n            onChange={(e) => modifier(\'email\', e.target.value)}\n            placeholder=\"vous@exemple.com\"\n            erreur={erreurs.email}\n          />\n        </Champ>\n      </div>\n\n      <div className=\"grid gap-6 sm:grid-cols-2\">\n        <Champ\n          id=\"telephone\"\n          label=\"Téléphone\"\n          erreur={erreurs.telephone}\n          indication=\"Indicatif Bénin par défaut, modifiable.\"\n        >\n          <div className=\"flex gap-2\">\n            <select\n              aria-label=\"Indicatif pays\"\n              value={valeurs.indicatif}\n              onChange={(e) =>\n                modifier(\'indicatif\', e.target.value)\n              }\n              className=\"w-28 rounded-xl border border-forest-100 bg-white px-3 py-3 text-ink focus:border-signal\"\n            >\n              <option value=\"+229\">+229</option>\n              <option value=\"+228\">+228</option>\n              <option value=\"+234\">+234</option>\n              <option value=\"+233\">+233</option>\n              <option value=\"+33\">+33</option>\n            </select>\n\n            <Saisie\n              id=\"telephone\"\n              name=\"telephone\"\n              type=\"tel\"\n              inputMode=\"tel\"\n              value={valeurs.telephone}\n              onChange={(e) =>\n                modifier(\'telephone\', e.target.value)\n              }\n              placeholder=\"64 54 99 59\"\n              erreur={erreurs.telephone}\n            />\n          </div>\n        </Champ>\n\n        <Champ id=\"domaine\" label=\"Domaine concerné\">\n          <Selection\n            id=\"domaine\"\n            name=\"domaine\"\n            value={valeurs.domaine}\n            onChange={(e) =>\n              modifier(\'domaine\', e.target.value)\n            }\n          >\n            {EXPERTISES.map((expertise) => (\n              <option\n                key={expertise.slug}\n                value={expertise.slug}\n              >\n                {expertise.titre}\n              </option>\n            ))}\n\n            <option value=\"autre\">Autre besoin</option>\n          </Selection>\n        </Champ>\n      </div>\n\n      <Champ\n        id=\"besoins\"\n        label=\"Décrivez vos besoins\"\n        erreur={erreurs.besoins}\n        indication=\"Matériel souhaité, quantités, lieu du chantier, délai attendu.\"\n      >\n        <ZoneTexte\n          id=\"besoins\"\n          name=\"besoins\"\n          value={valeurs.besoins}\n          onChange={(e) =>\n            modifier(\'besoins\', e.target.value)\n          }\n          placeholder={\n            \'Ex. :\\n- Câblage réseau de 12 postes à Houéyiho\\n- Fourniture d’un switch 24 ports\\n- Intervention souhaitée avant fin du mois\'\n          }\n          erreur={erreurs.besoins}\n        />\n      </Champ>\n\n      <div className=\"flex flex-wrap items-center gap-4\">\n        <Bouton\n          type=\"submit\"\n          disabled={envoiEnCours}\n        >\n          {envoiEnCours\n            ? \'Envoi en cours…\'\n            : \'Envoyer ma demande\'}\n        </Bouton>\n\n        <p className=\"text-xs text-slate-muted\">\n          Vos informations servent uniquement à établir votre devis.\n        </p>\n      </div>\n    </form>\n  );\n}\n```\n```jsx\nimport { useRef } from \'react\';\n\nimport { useDevisForm } from \'@/hooks/useDevisForm\';\nimport { Champ, Saisie, ZoneTexte, Selection } from \'@/components/ui/Champ\';\nimport Bouton from \'@/components/ui/Bouton\';\nimport { EXPERTISES } from \'@/data/expertises\';\nimport { cn } from \'@/utils/cn\';\n\nconst TYPES_CLIENT = [\n  {\n    valeur: \'societe\',\n    libelle: \'Société\',\n    detail: \'Entreprise, ONG, administration\',\n  },\n  {\n    valeur: \'particulier\',\n    libelle: \'Personne physique\',\n    detail: \'Particulier, artisan\',\n  },\n];\n\nexport default function FormulaireDevis() {\n  const {\n    valeurs,\n    erreurs,\n    envoiEnCours,\n    succes,\n    erreurGlobale,\n    modifier,\n    soumettre,\n    reinitialiser,\n  } = useDevisForm();\n\n  // Verrou immédiat contre les soumissions répétées.\n  const soumissionVerrouillee = useRef(false);\n\n  const gererSoumission = async (event) => {\n    if (soumissionVerrouillee.current || envoiEnCours) {\n      event.preventDefault();\n      return;\n    }\n\n    soumissionVerrouillee.current = true;\n\n    try {\n      await soumettre(event);\n    } finally {\n      soumissionVerrouillee.current = false;\n    }\n  };\n\n  if (succes) {\n    return (\n      <div className=\"rounded-2xl border border-forest-100 bg-forest-50 p-8\">\n        <h3 className=\"text-xl font-semibold\">Demande envoyée</h3>\n\n        <p className=\"mt-3 max-w-prose text-slate-muted\">\n          Nous avons bien reçu votre demande et revenons vers vous sous\n          48 heures ouvrées.\n          {succes.reference && (\n            <>\n              {\' \'}Conservez la référence{\' \'}\n              <strong className=\"text-forest-700\">\n                {succes.reference}\n              </strong>{\' \'}\n              pour tout échange.\n            </>\n          )}\n        </p>\n\n        <Bouton\n          onClick={reinitialiser}\n          variante=\"contour\"\n          className=\"mt-6\"\n        >\n          Envoyer une autre demande\n        </Bouton>\n      </div>\n    );\n  }\n\n  return (\n    <form\n      onSubmit={gererSoumission}\n      noValidate\n      className=\"space-y-7\"\n    >\n      {erreurGlobale && (\n        <p\n          role=\"alert\"\n          className=\"rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700\"\n        >\n          {erreurGlobale}\n        </p>\n      )}\n\n      <fieldset>\n        <legend className=\"text-sm font-semibold text-forest-700\">\n          Vous êtes\n        </legend>\n\n        <div className=\"mt-3 grid gap-3 sm:grid-cols-2\">\n          {TYPES_CLIENT.map((type) => (\n            <label\n              key={type.valeur}\n              className={cn(\n                \'cursor-pointer rounded-xl border p-4 transition-colors\',\n                valeurs.type_client === type.valeur\n                  ? \'border-signal bg-forest-50\'\n                  : \'border-forest-100 hover:border-forest-200\'\n              )}\n            >\n              <input\n                type=\"radio\"\n                name=\"type_client\"\n                value={type.valeur}\n                checked={valeurs.type_client === type.valeur}\n                onChange={(e) =>\n                  modifier(\'type_client\', e.target.value)\n                }\n                className=\"sr-only\"\n              />\n\n              <span className=\"block font-semibold text-ink\">\n                {type.libelle}\n              </span>\n\n              <span className=\"mt-1 block text-xs text-slate-muted\">\n                {type.detail}\n              </span>\n            </label>\n          ))}\n        </div>\n      </fieldset>\n\n      {valeurs.type_client === \'societe\' && (\n        <Champ\n          id=\"raison_sociale\"\n          label=\"Nom de la société\"\n          erreur={erreurs.raison_sociale}\n        >\n          <Saisie\n            id=\"raison_sociale\"\n            name=\"raison_sociale\"\n            value={valeurs.raison_sociale}\n            onChange={(e) =>\n              modifier(\'raison_sociale\', e.target.value)\n            }\n            placeholder=\"Ex. PLANETECH SARL\"\n            erreur={erreurs.raison_sociale}\n          />\n        </Champ>\n      )}\n\n      <div className=\"grid gap-6 sm:grid-cols-2\">\n        <Champ\n          id=\"nom\"\n          label={\n            valeurs.type_client === \'societe\'\n              ? \'Nom du contact\'\n              : \'Nom et prénom\'\n          }\n          erreur={erreurs.nom}\n        >\n          <Saisie\n            id=\"nom\"\n            name=\"nom\"\n            value={valeurs.nom}\n            onChange={(e) => modifier(\'nom\', e.target.value)}\n            placeholder=\"Ex. Armelle Assogba\"\n            erreur={erreurs.nom}\n          />\n        </Champ>\n\n        <Champ\n          id=\"email\"\n          label=\"Adresse email\"\n          erreur={erreurs.email}\n        >\n          <Saisie\n            id=\"email\"\n            name=\"email\"\n            type=\"email\"\n            inputMode=\"email\"\n            value={valeurs.email}\n            onChange={(e) => modifier(\'email\', e.target.value)}\n            placeholder=\"vous@exemple.com\"\n            erreur={erreurs.email}\n          />\n        </Champ>\n      </div>\n\n      <div className=\"grid gap-6 sm:grid-cols-2\">\n        <Champ\n          id=\"telephone\"\n          label=\"Téléphone\"\n          erreur={erreurs.telephone}\n          indication=\"Indicatif Bénin par défaut, modifiable.\"\n        >\n          <div className=\"flex gap-2\">\n            <select\n              aria-label=\"Indicatif pays\"\n              value={valeurs.indicatif}\n              onChange={(e) =>\n                modifier(\'indicatif\', e.target.value)\n              }\n              className=\"w-28 rounded-xl border border-forest-100 bg-white px-3 py-3 text-ink focus:border-signal\"\n            >\n              <option value=\"+229\">+229</option>\n              <option value=\"+228\">+228</option>\n              <option value=\"+234\">+234</option>\n              <option value=\"+233\">+233</option>\n              <option value=\"+33\">+33</option>\n            </select>\n\n            <Saisie\n              id=\"telephone\"\n              name=\"telephone\"\n              type=\"tel\"\n              inputMode=\"tel\"\n              value={valeurs.telephone}\n              onChange={(e) =>\n                modifier(\'telephone\', e.target.value)\n              }\n              placeholder=\"64 54 99 59\"\n              erreur={erreurs.telephone}\n            />\n          </div>\n        </Champ>\n\n        <Champ id=\"domaine\" label=\"Domaine concerné\">\n          <Selection\n            id=\"domaine\"\n            name=\"domaine\"\n            value={valeurs.domaine}\n            onChange={(e) =>\n              modifier(\'domaine\', e.target.value)\n            }\n          >\n            {EXPERTISES.map((expertise) => (\n              <option\n                key={expertise.slug}\n                value={expertise.slug}\n              >\n                {expertise.titre}\n              </option>\n            ))}\n\n            <option value=\"autre\">Autre besoin</option>\n          </Selection>\n        </Champ>\n      </div>\n\n      <Champ\n        id=\"besoins\"\n        label=\"Décrivez vos besoins\"\n        erreur={erreurs.besoins}\n        indication=\"Matériel souhaité, quantités, lieu du chantier, délai attendu.\"\n      >\n        <ZoneTexte\n          id=\"besoins\"\n          name=\"besoins\"\n          value={valeurs.besoins}\n          onChange={(e) =>\n            modifier(\'besoins\', e.target.value)\n          }\n          placeholder={\n            \'Ex. :\\n- Câblage réseau de 12 postes à Houéyiho\\n- Fourniture d’un switch 24 ports\\n- Intervention souhaitée avant fin du mois\'\n          }\n          erreur={erreurs.besoins}\n        />\n      </Champ>\n\n      <div className=\"flex flex-wrap items-center gap-4\">\n        <Bouton\n          type=\"submit\"\n          disabled={envoiEnCours}\n        >\n          {envoiEnCours\n            ? \'Envoi en cours…\'\n            : \'Envoyer ma demande\'}\n        </Bouton>\n\n        <p className=\"text-xs text-slate-muted\">\n          Vos informations servent uniquement à établir votre devis.\n        </p>\n      </div>\n    </form>\n  );\n}\n```\n```jsx\nimport { useRef } from \'react\';\n\nimport { useDevisForm } from \'@/hooks/useDevisForm\';\nimport { Champ, Saisie, ZoneTexte, Selection } from \'@/components/ui/Champ\';\nimport Bouton from \'@/components/ui/Bouton\';\nimport { EXPERTISES } from \'@/data/expertises\';\nimport { cn } from \'@/utils/cn\';\n\nconst TYPES_CLIENT = [\n  {\n    valeur: \'societe\',\n    libelle: \'Société\',\n    detail: \'Entreprise, ONG, administration\',\n  },\n  {\n    valeur: \'particulier\',\n    libelle: \'Personne physique\',\n    detail: \'Particulier, artisan\',\n  },\n];\n\nexport default function FormulaireDevis() {\n  const {\n    valeurs,\n    erreurs,\n    envoiEnCours,\n    succes,\n    erreurGlobale,\n    modifier,\n    soumettre,\n    reinitialiser,\n  } = useDevisForm();\n\n  // Verrou immédiat contre les soumissions répétées.\n  const soumissionVerrouillee = useRef(false);\n\n  const gererSoumission = async (event) => {\n    if (soumissionVerrouillee.current || envoiEnCours) {\n      event.preventDefault();\n      return;\n    }\n\n    soumissionVerrouillee.current = true;\n\n    try {\n      await soumettre(event);\n    } finally {\n      soumissionVerrouillee.current = false;\n    }\n  };\n\n  if (succes) {\n    return (\n      <div className=\"rounded-2xl border border-forest-100 bg-forest-50 p-8\">\n        <h3 className=\"text-xl font-semibold\">Demande envoyée</h3>\n\n        <p className=\"mt-3 max-w-prose text-slate-muted\">\n          Nous avons bien reçu votre demande et revenons vers vous sous\n          48 heures ouvrées.\n          {succes.reference && (\n            <>\n              {\' \'}Conservez la référence{\' \'}\n              <strong className=\"text-forest-700\">\n                {succes.reference}\n              </strong>{\' \'}\n              pour tout échange.\n            </>\n          )}\n        </p>\n\n        <Bouton\n          onClick={reinitialiser}\n          variante=\"contour\"\n          className=\"mt-6\"\n        >\n          Envoyer une autre demande\n        </Bouton>\n      </div>\n    );\n  }\n\n  return (\n    <form\n      onSubmit={gererSoumission}\n      noValidate\n      className=\"space-y-7\"\n    >\n      {erreurGlobale && (\n        <p\n          role=\"alert\"\n          className=\"rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700\"\n        >\n          {erreurGlobale}\n        </p>\n      )}\n\n      <fieldset>\n        <legend className=\"text-sm font-semibold text-forest-700\">\n          Vous êtes\n        </legend>\n\n        <div className=\"mt-3 grid gap-3 sm:grid-cols-2\">\n          {TYPES_CLIENT.map((type) => (\n            <label\n              key={type.valeur}\n              className={cn(\n                \'cursor-pointer rounded-xl border p-4 transition-colors\',\n                valeurs.type_client === type.valeur\n                  ? \'border-signal bg-forest-50\'\n                  : \'border-forest-100 hover:border-forest-200\'\n              )}\n            >\n              <input\n                type=\"radio\"\n                name=\"type_client\"\n                value={type.valeur}\n                checked={valeurs.type_client === type.valeur}\n                onChange={(e) =>\n                  modifier(\'type_client\', e.target.value)\n                }\n                className=\"sr-only\"\n              />\n\n              <span className=\"block font-semibold text-ink\">\n                {type.libelle}\n              </span>\n\n              <span className=\"mt-1 block text-xs text-slate-muted\">\n                {type.detail}\n              </span>\n            </label>\n          ))}\n        </div>\n      </fieldset>\n\n      {valeurs.type_client === \'societe\' && (\n        <Champ\n          id=\"raison_sociale\"\n          label=\"Nom de la société\"\n          erreur={erreurs.raison_sociale}\n        >\n          <Saisie\n            id=\"raison_sociale\"\n            name=\"raison_sociale\"\n            value={valeurs.raison_sociale}\n            onChange={(e) =>\n              modifier(\'raison_sociale\', e.target.value)\n            }\n            placeholder=\"Ex. PLANETECH SARL\"\n            erreur={erreurs.raison_sociale}\n          />\n        </Champ>\n      )}\n\n      <div className=\"grid gap-6 sm:grid-cols-2\">\n        <Champ\n          id=\"nom\"\n          label={\n            valeurs.type_client === \'societe\'\n              ? \'Nom du contact\'\n              : \'Nom et prénom\'\n          }\n          erreur={erreurs.nom}\n        >\n          <Saisie\n            id=\"nom\"\n            name=\"nom\"\n            value={valeurs.nom}\n            onChange={(e) => modifier(\'nom\', e.target.value)}\n            placeholder=\"Ex. Armelle Assogba\"\n            erreur={erreurs.nom}\n          />\n        </Champ>\n\n        <Champ\n          id=\"email\"\n          label=\"Adresse email\"\n          erreur={erreurs.email}\n        >\n          <Saisie\n            id=\"email\"\n            name=\"email\"\n            type=\"email\"\n            inputMode=\"email\"\n            value={valeurs.email}\n            onChange={(e) => modifier(\'email\', e.target.value)}\n            placeholder=\"vous@exemple.com\"\n            erreur={erreurs.email}\n          />\n        </Champ>\n      </div>\n\n      <div className=\"grid gap-6 sm:grid-cols-2\">\n        <Champ\n          id=\"telephone\"\n          label=\"Téléphone\"\n          erreur={erreurs.telephone}\n          indication=\"Indicatif Bénin par défaut, modifiable.\"\n        >\n          <div className=\"flex gap-2\">\n            <select\n              aria-label=\"Indicatif pays\"\n              value={valeurs.indicatif}\n              onChange={(e) =>\n                modifier(\'indicatif\', e.target.value)\n              }\n              className=\"w-28 rounded-xl border border-forest-100 bg-white px-3 py-3 text-ink focus:border-signal\"\n            >\n              <option value=\"+229\">+229</option>\n              <option value=\"+228\">+228</option>\n              <option value=\"+234\">+234</option>\n              <option value=\"+233\">+233</option>\n              <option value=\"+33\">+33</option>\n            </select>\n\n            <Saisie\n              id=\"telephone\"\n              name=\"telephone\"\n              type=\"tel\"\n              inputMode=\"tel\"\n              value={valeurs.telephone}\n              onChange={(e) =>\n                modifier(\'telephone\', e.target.value)\n              }\n              placeholder=\"64 54 99 59\"\n              erreur={erreurs.telephone}\n            />\n          </div>\n        </Champ>\n\n        <Champ id=\"domaine\" label=\"Domaine concerné\">\n          <Selection\n            id=\"domaine\"\n            name=\"domaine\"\n            value={valeurs.domaine}\n            onChange={(e) =>\n              modifier(\'domaine\', e.target.value)\n            }\n          >\n            {EXPERTISES.map((expertise) => (\n              <option\n                key={expertise.slug}\n                value={expertise.slug}\n              >\n                {expertise.titre}\n              </option>\n            ))}\n\n            <option value=\"autre\">Autre besoin</option>\n          </Selection>\n        </Champ>\n      </div>\n\n      <Champ\n        id=\"besoins\"\n        label=\"Décrivez vos besoins\"\n        erreur={erreurs.besoins}\n        indication=\"Matériel souhaité, quantités, lieu du chantier, délai attendu.\"\n      >\n        <ZoneTexte\n          id=\"besoins\"\n          name=\"besoins\"\n          value={valeurs.besoins}\n          onChange={(e) =>\n            modifier(\'besoins\', e.target.value)\n          }\n          placeholder={\n            \'Ex. :\\n- Câblage réseau de 12 postes à Houéyiho\\n- Fourniture d’un switch 24 ports\\n- Intervention souhaitée avant fin du mois\'\n          }\n          erreur={erreurs.besoins}\n        />\n      </Champ>\n\n      <div className=\"flex flex-wrap items-center gap-4\">\n        <Bouton\n          type=\"submit\"\n          disabled={envoiEnCours}\n        >\n          {envoiEnCours\n            ? \'Envoi en cours…\'\n            : \'Envoyer ma demande\'}\n        </Bouton>\n\n        <p className=\"text-xs text-slate-muted\">\n          Vos informations servent uniquement à établir votre devis.\n        </p>\n      </div>\n    </form>\n  );\n}\n```','en_attente','2026-09-29 07:40:32','2026-09-29 07:40:32'),(24,'DEV-6ABB7A905CAEF','societe','ig_yègi_yèg_y','iugtfvuitgvyiè','boscorethice5@gmail.com','+229','14253625','informatique','iègt_y-xdecrtfvbynu_r-vtyiègt_y-xdecrtfvbynu_r-vtyiègt_y-xdecrtfvbynu_r-vtyiègt_y-xdecrtfvbynu_r-vtyiègt_y-xdecrtfvbynu_r-vtyiègt_y-xdecrtfvbynu_r-vtyiègt_y-xdecrtfvbynu_r-vty','en_attente','2026-09-29 07:45:04','2026-09-29 07:45:04'),(25,'DEV-6ABB7B4215480','societe','yrtrctc','u-ffgtvyucfg','delerethice@gmail.com','+229','25255252','informatique','```php\n<?php\n\nnamespace App\\Http\\Controllers\\Api;\n\nuse App\\Http\\Controllers\\Controller;\nuse App\\Mail\\DevisConfirmationMail;\nuse App\\Models\\DemandeDevis;\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Support\\Facades\\Log;\nuse Illuminate\\Support\\Facades\\Mail;\n\nclass DevisController extends Controller\n{\n    /**\n     * Enregistrer une nouvelle demande de devis.\n     */\n    public function store(Request $request)\n    {\n        $validated = $request->validate([\n            \'type_client\' => [\n                \'required\',\n                \'in:societe,particulier\',\n            ],\n\n            \'raison_sociale\' => [\n                \'required_if:type_client,societe\',\n                \'nullable\',\n                \'string\',\n                \'max:255\',\n            ],\n\n            \'nom\' => [\n                \'required\',\n                \'string\',\n                \'max:255\',\n            ],\n\n            \'email\' => [\n                \'required\',\n                \'email\',\n                \'max:255\',\n            ],\n\n            \'indicatif\' => [\n                \'required\',\n                \'string\',\n                \'max:10\',\n            ],\n\n            \'telephone\' => [\n                \'required\',\n                \'string\',\n                \'max:50\',\n            ],\n\n            \'domaine\' => [\n                \'required\',\n                \'string\',\n                \'max:255\',\n            ],\n\n            \'besoins\' => [\n                \'required\',\n                \'string\',\n            ],\n        ]);\n\n        /*\n        |--------------------------------------------------------------------------\n        | Création de la demande\n        |--------------------------------------------------------------------------\n        */\n\n        $demande = DemandeDevis::create($validated);\n\n        /*\n        |--------------------------------------------------------------------------\n        | Email de confirmation au client\n        |--------------------------------------------------------------------------\n        */\n\n        try {\n            Mail::to($demande->email)\n                ->send(new DevisConfirmationMail($demande));\n\n            Log::info(\'Email de confirmation client envoyé.\', [\n                \'demande_id\' => $demande->id,\n                \'email\' => $demande->email,\n                \'reference\' => $demande->reference,\n            ]);\n        } catch (\\Throwable $e) {\n            Log::error(\'Erreur email de confirmation client.\', [\n                \'demande_id\' => $demande->id,\n                \'email\' => $demande->email,\n                \'reference\' => $demande->reference,\n                \'error\' => $e->getMessage(),\n            ]);\n        }\n\n        /*\n        |--------------------------------------------------------------------------\n        | Notification interne à PLANETECH\n        |--------------------------------------------------------------------------\n        |\n        | L\'adresse de réception est récupérée depuis MAIL_FROM_ADDRESS\n        | dans le fichier .env, via la configuration Laravel.\n        |\n        */\n\n        $adresseNotification = trim(\n            (string) config(\'mail.from.address\')\n        );\n\n        // Normaliser les adresses pour comparer sans tenir compte\n        // des majuscules ou des espaces.\n        $emailClient = strtolower(trim($demande->email));\n        $emailNotification = strtolower($adresseNotification);\n\n        if ($adresseNotification === \'\') {\n            Log::warning(\n                \'Notification PLANETECH non envoyée : MAIL_FROM_ADDRESS non configurée.\',\n                [\n                    \'demande_id\' => $demande->id,\n                    \'reference\' => $demande->reference,\n                ]\n            );\n        } elseif ($emailClient === $emailNotification) {\n            /*\n             * Si le client utilise la même adresse que celle configurée\n             * pour PLANETECH, ne pas lui envoyer une deuxième copie.\n             */\n            Log::info(\n                \'Notification interne ignorée : le client utilise déjà cette adresse.\',\n                [\n                    \'demande_id\' => $demande->id,\n                    \'reference\' => $demande->reference,\n                    \'email\' => $adresseNotification,\n                ]\n            );\n        } else {\n            try {\n                $contenu =\n                    \"Nouvelle demande de devis PLANETECH\\n\\n\" .\n                    \"Référence : {$demande->reference}\\n\" .\n                    \"Type de client : {$demande->type_client}\\n\" .\n                    \"Société : \" .\n                    ($demande->raison_sociale ?: \'Non renseignée\') . \"\\n\" .\n                    \"Nom : {$demande->nom}\\n\" .\n                    \"Email client : {$demande->email}\\n\" .\n                    \"Téléphone : {$demande->indicatif} {$demande->telephone}\\n\" .\n                    \"Domaine : {$demande->domaine}\\n\\n\" .\n                    \"Besoins du client :\\n\" .\n                    $demande->besoins;\n\n                Mail::raw(\n                    $contenu,\n                    function ($message) use (\n                        $demande,\n                        $adresseNotification\n                    ) {\n                        $message\n                            ->to($adresseNotification)\n                            ->replyTo(\n                                $demande->email,\n                                $demande->nom\n                            )\n                            ->subject(\n                                \'Nouvelle demande de devis - \' .\n                                $demande->reference\n                            );\n                    }\n                );\n\n                Log::info(\'Notification PLANETECH envoyée.\', [\n                    \'demande_id\' => $demande->id,\n                    \'email\' => $adresseNotification,\n                    \'reference\' => $demande->reference,\n                ]);\n            } catch (\\Throwable $e) {\n                Log::error(\'Erreur notification PLANETECH.\', [\n                    \'demande_id\' => $demande->id,\n                    \'email\' => $adresseNotification,\n                    \'reference\' => $demande->reference,\n                    \'error\' => $e->getMessage(),\n                ]);\n            }\n        }\n\n        /*\n        |--------------------------------------------------------------------------\n        | Réponse API\n        |--------------------------------------------------------------------------\n        */\n\n        return response()->json([\n            \'message\' => \'Demande de devis enregistrée avec succès.\',\n            \'reference\' => $demande->reference,\n            \'demande\' => $demande,\n        ], 201);\n    }\n\n    /**\n     * Lister toutes les demandes de devis.\n     */\n    public function listes_devis()\n    {\n        $demandes = DemandeDevis::latest()->get();\n\n        return response()->json($demandes);\n    }\n\n    /**\n     * Modifier le statut d\'une demande de devis.\n     */\n    public function updateStatut(\n        Request $request,\n        DemandeDevis $demandeDevis\n    ) {\n        $validated = $request->validate([\n            \'statut\' => [\n                \'required\',\n                \'string\',\n                \'max:50\',\n            ],\n        ]);\n\n        $demandeDevis->update($validated);\n\n        return response()->json([\n            \'message\' => \'Statut de la demande mis à jour avec succès.\',\n            \'demande\' => $demandeDevis,\n        ]);\n    }\n\n    /**\n     * Supprimer une demande de devis.\n     */\n    public function destroy(DemandeDevis $demandeDevis)\n    {\n        $demandeDevis->delete();\n\n        return response()->json([\n            \'message\' => \'Demande de devis supprimée avec succès.\',\n        ]);\n    }\n}\n```','en_attente','2026-09-29 07:48:02','2026-09-29 07:48:02'),(26,'DEV-6ABB7BF3DE620','societe','erxycvubhi','_rgèytghèy','delerethice@gmail.com','+229','14253625','informatique','fpkfjnbtdfqdjpxrfpkfjnbtdfqdjpxrfpkfjnbtdfqdjpxrfpkfjnbtdfqdjpxrfpkfjnbtdfqdjpxrfpkfjnbtdfqdjpxrfpkfjnbtdfqdjpxr','envoye','2026-09-29 07:50:59','2026-09-29 08:26:22'),(27,'DEV-6ABB84B2A85BA','societe','cyugtvb','igyèhbiy','delerethice@gmail.com','+229','56565656','informatique','hytwxycrdtfuvgyibhunsrdctfvgyhurdyctfvgybhujydfvtgybhujrydctfvgybunhji','en_attente','2026-09-29 08:28:18','2026-09-29 08:28:18'),(28,'DEV-6ABB84E48FC50','societe','ryxcr(vyug','_y-g_ègh','delerethice@gmail.com','+229','565656565','informatique','fgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvg','en_attente','2026-09-29 08:29:08','2026-09-29 08:29:08'),(29,'DEV-6ABB9CF8C7CCB','societe','jductvgfvuy','tryxfr','delerethice@gmail.com','+229','14253625','informatique','hydrxcvuygibh_rcftghuucritvybdexcrvtbyncrf-tvyurtgbynuucrtègy_u-frtgèhy','en_attente','2026-09-29 10:11:52','2026-09-29 10:11:52'),(30,'DEV-6ABB9D440313E','societe','ydxrctfgivuh','rducfygvb','boscorethice5@gmail.com','+229','14253625','informatique','fgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvgfgxdrctrcftcvg','en_attente','2026-09-29 10:13:08','2026-09-29 10:13:08'),(31,'DEV-6ABBA29ACC097','societe','riygvfyghv','hredxyhfcvug','delerethice@gmail.com','+229','65658585','informatique','ceci est un l\'enregistrement ne se','envoye','2026-09-29 10:35:54','2026-09-30 09:44:48'),(32,'DEV-6ABBCD8BD0C50','particulier',NULL,'yrjdtfkuvu','boscorethice5@gmail.com','+229','25525252','informatique','zsedrtfgyhuuze(sd-itoyiesdfrtuiedfogèyhuiuertèy_urdhxcfrvitbyotdxcfyvuhrdtcfuvyibukxtcybu','envoye','2026-09-29 13:39:07','2026-09-29 13:47:22'),(33,'DEV-6ABCE8B07FC73','societe','AZSDFD','eudr-dutèdfj','delerethice@gmail.com','+229','2552525